app = Flask(__name__)

# In-memory data store for single-user todo app
# Lists structure: { list_id: { 'id': list_id, 'name': name } }
# Tasks structure: { task_id: { 'id': task_id, 'list_id': list_id, 'text': text, 'completed': bool } }
